use clap::Subcommand;

use heisenberg_project_model::clippy_lint_path::clippy_lint_path;
use heisenberg_project_model::constants::CARGO_BUILD_TABLE;
use heisenberg_project_model::constants::CARGO_ENVIRONMENT_TABLE;
use heisenberg_project_model::constants::CARGO_RUSTFLAGS;
use heisenberg_project_model::constants::CARGO_TARGET_TABLE;
use heisenberg_project_model::constants::CLIPPY_ARGUMENTS_VARIABLE;
use heisenberg_project_model::constants::CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE;
use heisenberg_project_model::constants::CLIPPY_CONFIGURATION_FILE;
use heisenberg_project_model::constants::CLIPPY_DENIED_LINTS;
use heisenberg_project_model::constants::CLIPPY_HIDDEN_CONFIGURATION_FILE;
use heisenberg_project_model::constants::CLIPPY_TEST_ALLOWANCES;
use heisenberg_project_model::constants::NIGHTLY_BOOTSTRAP_VARIABLE;
use heisenberg_project_model::constants::NIGHTLY_FEATURE_VARIABLES;
use heisenberg_project_model::constants::RUSTFLAGS_VARIABLES;
use heisenberg_project_model::constants::SUPPORTED_TARGETS;

use crate::check_command::CheckCommand;
use crate::constants::SUPPORTED_RUST_VERSION;

#[derive(Debug, Subcommand)]
pub enum HeisenbergSubcommand {
    #[command(
        about = "Report module dependency cycles and structural violations in every crate of a Cargo workspace, for every supported target",
        long_about = format!("Report module dependency cycles and structural violations in every crate of a Cargo workspace, for {}.\n\nPrecondition: rustc {SUPPORTED_RUST_VERSION} compiles the workspace for every supported target, Cargo.lock is up to date, the cargo home holds every package of Cargo.lock (`cargo fetch`), the build runs from the workspace directory with the environment Heisenberg runs with and without --config arguments, and clippy runs without command-line arguments. An environment variable whose name or value is not UTF-8, {rustflags_variables}, {CLIPPY_ARGUMENTS_VARIABLE}, {CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE} or {nightly_feature_variables} in the environment, a workspace directory that is not the root of its cargo workspace, a workspace member or crate root outside the workspace root, a package whose metadata cargo_metadata cannot read, a crate root that two targets share or that cannot be read, a metabuild script, which has no source file, a workspace root, target directory or crate root that is not an absolute UTF-8 path, a {CLIPPY_CONFIGURATION_FILE} or {CLIPPY_HIDDEN_CONFIGURATION_FILE} that discovery finds and cannot read, or that is the only one in its directory and is not valid TOML, {CARGO_RUSTFLAGS} in the [{CARGO_BUILD_TABLE}] or [{CARGO_TARGET_TABLE}] tables of the cargo configuration or in the {build_rustflags_variable} and {target_rustflags_variable} variables of a supported target, and {CLIPPY_ARGUMENTS_VARIABLE}, {CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE} or {NIGHTLY_BOOTSTRAP_VARIABLE} in the [{CARGO_ENVIRONMENT_TABLE}] table of the cargo configuration, under any letter case, fail the run.\n\nThe analysis enables all features, test and debug assertions. Violations: paths, macro calls, attributes, derives, modules and extern crates that do not resolve; items whose syntax rust-analyzer cannot map to their definition, such as items of a block inside a type; module files declared inside a block, which are not analysed, while the paths written in a module declared inline inside a block are dependencies of the own code of the module that holds the block; cfg_select! calls, whose unselected arms escape the analysis; invalid macro definitions; macro expansions that fail or cannot be parsed; built-in macros that are not implemented; cfg and cfg_attr predicates that negate a feature, test or debug_assertions; allow and expect attributes of any lint, and warn attributes that lower {denied_lints} or their group, including those a cfg_attr applies or a workspace member's macro writes; a workspace member whose lints, after workspace inheritance, allow any lint of any tool; comments other than doc comments, in module files and in the files they include; code active on no supported target; glob imports; re-exports; a second public item in a module, constants and modules aside; a public constant outside the crate's constants module, crate::constants; a public item other than a constant or a module inside it; a public associated constant of an inherent impl; an impl block outside the file of the struct, enum or union it implements; a blanket impl, whose self type is a type parameter, outside the file of its trait; an impl block that implements neither a struct, enum or union of its crate nor, as a blanket impl, a trait of its crate; an integration test target holding anything but tests, constants, imports and modules, where a test is a function under the built-in test, bench or test_case attribute; a module file shared by several modules, or by two modules of one crate, which leaves the second unanalysed; packages that depend on each other, or a package on itself, through dev-dependencies, each package named with its version, where dependencies on packages without a library are ignored as cargo ignores them; a tests-only package whose tests need no test library; a workspace member whose lints, after workspace inheritance and in cargo's order, leave any of {denied_lints}, under either spelling of its name or a name clippy renamed to it, below deny; a workspace member with no {CLIPPY_CONFIGURATION_FILE} or {CLIPPY_HIDDEN_CONFIGURATION_FILE} in its directory or an ancestor within the workspace, or whose nearest such directory holds both; and a clippy configuration that does not set each of {test_allowances} to true, which is the only way tests may use them.\n\nEvery decision is semantic, as rust-analyzer resolves the code: an item is public when its visibility reaches beyond its own module, so a `pub(self)` item is not public while a `pub` item of a private module is, and a `macro_rules!` macro is public when exported; a name bound by an unresolved import, whether a path or a macro call, belongs to that import's issue; a library is empty when it defines nothing on any supported target; a module file that its own attributes configure out is inactive code at its declaration, where its predicate, when it negates a feature, test or debug_assertions, is reported unless an analysis of that same declaration reports it where it is written.\n\nIssues are grouped by type, in one section per type: a `<IssueType>: <count> violation(s)` line, a line that states the purpose of the rule and what to do, an empty line, and one `- <file>[:<line>:<column>]: <message>` line per issue, followed, four spaces in, by its source line when it has one and by further indented lines that list the dependencies of a cycle, the inclusions of a shared module file, the failing expansions of a macro call or the impl blocks of a flagged type. Each issue is reported once, at the name of the item it concerns; when it holds only in some of the crate targets or platforms that analyse its file, the message names them. A cause and its direct consequences form one issue: a shared module subtree is reported at its root file, the impl blocks of a flagged type of an integration test target within the type's issue, and every failing expansion within the macro call written in the source. Shared module files are analysed in every crate that includes them. The public item, constant and integration test target rules apply to items written in module files; an item that an attribute macro rewrites is analysed through the items of its expansion that rust-analyzer maps back to it, and the rest of the expansion, like the items other macros generate, is trusted. Derive macro output is analysed like any macro expansion, except that of the built-in derives that rust-analyzer records as impls of their trait without expanding them, which is trusted; an expansion that cannot be parsed is reported at the macro call written in the source and not analysed further, even when a macro of another crate wrote the call that produced it. Procedural macros and build scripts never run: items under procedural macro attributes are analysed as written, with the attributes they may consume trusted, and in an integration test target they are trusted as their macro's input, text written outside a crate's module files, such as in other crates or in included files, is trusted, apart from the comments of included files, and results reflect the files on disk, including generated ones.", SUPPORTED_TARGETS.map(|target| target.triple()).join(" and "),
            build_rustflags_variable = format!("CARGO_{CARGO_BUILD_TABLE}_{CARGO_RUSTFLAGS}").to_uppercase(),
            target_rustflags_variable = format!("CARGO_{CARGO_TARGET_TABLE}_<TRIPLE>_{CARGO_RUSTFLAGS}").to_uppercase(),
            denied_lints = CLIPPY_DENIED_LINTS.map(|lint| clippy_lint_path(lint.name)).join(", "),
            nightly_feature_variables = NIGHTLY_FEATURE_VARIABLES.join(", "),
            rustflags_variables = RUSTFLAGS_VARIABLES.join(", "),
            test_allowances = CLIPPY_TEST_ALLOWANCES.join(", "))
    )]
    Check(CheckCommand),
}
